package data

// Script constants: the Mobius enums and constant classes that the Lua
// quest scripts use as global tables (State.STARTED, QuestSound.X,
// ClassId.FIGHTER, SystemMessageId.X, ...), generated by cmd/datagen and
// loaded with LoadConstants.

import (
	"fmt"
	"io/fs"
	"maps"
	"os"
	"regexp"
	"slices"
	"strings"
)

// ConstantsFile is the path of the script constant file, relative to the
// data folder.
const ConstantsFile = "constants/constants.json"

// The constant tables the file must hold, by Lua name. Each mirrors a Mobius
// class:
//   - Category: CategoryType, the CategoryType values;
//   - ChatType: ChatType, the client IDs (NPC_GENERAL and NPC_SHOUT repeat
//     GENERAL and SHOUT);
//   - ClassId: PlayerClass, the class IDs (PlayerClass gives their level,
//     race, parent and mage flag);
//   - Paperdoll: the Inventory.PAPERDOLL_* slots without the prefix (RHAND);
//   - QuestSound: QuestSound, the sound names its PlaySound packets play;
//   - QuestType: QuestType, the ordinals;
//   - Race: Race, the Race values (the client race IDs);
//   - Sex: Sex, the ordinals;
//   - State: the quest states CREATED, STARTED and COMPLETED (0, 1, 2);
//   - SystemMessageId: the system message IDs.
const (
	ConstCategory        = "Category"
	ConstChatType        = "ChatType"
	ConstClassID         = "ClassId"
	ConstPaperdoll       = "Paperdoll"
	ConstQuestSound      = "QuestSound"
	ConstQuestType       = "QuestType"
	ConstRace            = "Race"
	ConstSex             = "Sex"
	ConstState           = "State"
	ConstSystemMessageID = "SystemMessageId"
)

// ConstantTableNames returns the names of the tables the constant file
// must hold, sorted.
func ConstantTableNames() []string {
	return []string{
		ConstCategory, ConstChatType, ConstClassID, ConstPaperdoll, ConstQuestSound,
		ConstQuestType, ConstRace, ConstSex, ConstState, ConstSystemMessageID,
	}
}

// stringConstantTables are the tables whose values are strings; the others
// hold integers.
var stringConstantTables = []string{ConstQuestSound}

// ConstantTable is one table of named constants: a global table of the Lua
// scripts. Exactly one of Ints and Strings is set.
type ConstantTable struct {
	// Name is the name of the Lua table, such as "State".
	Name string `json:"name"`
	// Source is the Mobius class it comes from, such as
	// "mechanics/script/State".
	Source string `json:"source"`
	// Ints maps constant names to integer values.
	Ints map[string]int `json:"ints,omitempty"`
	// Strings maps constant names to string values.
	Strings map[string]string `json:"strings,omitempty"`
}

// Len returns the number of constants in t.
func (t *ConstantTable) Len() int { return len(t.Ints) + len(t.Strings) }

// Constants is the checked script constant data. It must not be modified
// after NewConstants or LoadConstants returns, and is then safe for
// concurrent use.
type Constants struct {
	// Tables are sorted by name.
	Tables []ConstantTable

	byName map[string]int // table name -> index in Tables
}

// LoadConstants reads and checks the constant file in dir.
func LoadConstants(dir string) (*Constants, error) {
	c, err := LoadConstantsFS(os.DirFS(dir))
	if err != nil {
		return nil, fmt.Errorf("%w (data folder %s)", err, dir)
	}
	return c, nil
}

// LoadConstantsFS reads and checks the constant file in fsys.
func LoadConstantsFS(fsys fs.FS) (*Constants, error) {
	var tables []ConstantTable
	if err := readJSON(fsys, ConstantsFile, &tables); err != nil {
		return nil, err
	}
	return NewConstants(tables)
}

// constNameRe matches a constant name: an upper case Lua identifier, like
// the Mobius names, which never clashes with the (lowercase) Lua keywords.
var constNameRe = regexp.MustCompile(`^[A-Z_][A-Z0-9_]*$`)

// NewConstants checks the tables and indexes them. The slice is used as it
// is. The rules:
//   - the tables are sorted by name, unique, and exactly those of
//     ConstantTableNames;
//   - QuestSound holds strings, the others integers, and none is empty;
//   - every constant name is an upper case Lua identifier;
//   - ClassId, Race and Category match the generated PlayerClass, Race and
//     CategoryType enums value for value, so scripts and Go code agree.
func NewConstants(tables []ConstantTable) (*Constants, error) {
	c := &Constants{Tables: tables, byName: make(map[string]int, len(tables))}
	var p problems
	for i := range tables {
		t := &tables[i]
		where := fmt.Sprintf("%s: table %q", ConstantsFile, t.Name)
		if _, dup := c.byName[t.Name]; dup {
			p.addf("%s: duplicate name", where)
			continue
		}
		c.byName[t.Name] = i
		if i > 0 && tables[i-1].Name > t.Name {
			p.addf("%s: tables are not sorted by name", where)
		}
		if !slices.Contains(ConstantTableNames(), t.Name) {
			p.addf("%s: unknown table", where)
			continue
		}
		wantStrings := slices.Contains(stringConstantTables, t.Name)
		switch {
		case len(t.Ints) > 0 && len(t.Strings) > 0:
			p.addf("%s: has both integer and string values", where)
		case wantStrings && len(t.Strings) == 0:
			p.addf("%s: no string values", where)
		case !wantStrings && len(t.Ints) == 0:
			p.addf("%s: no integer values", where)
		}
		names := append(slices.Sorted(maps.Keys(t.Ints)), slices.Sorted(maps.Keys(t.Strings))...)
		for _, name := range names {
			if !constNameRe.MatchString(name) {
				p.addf("%s: constant %q is not an upper case Lua name", where, name)
			}
		}
		checkEnumTable(&p, where, t)
	}
	for _, name := range ConstantTableNames() {
		if _, ok := c.byName[name]; !ok {
			p.addf("%s: table %q is missing", ConstantsFile, name)
		}
	}
	if err := p.err(); err != nil {
		return nil, err
	}
	return c, nil
}

// checkEnumTable checks that a table mirroring a generated enum holds
// exactly its values.
func checkEnumTable(p *problems, where string, t *ConstantTable) {
	var want map[string]int
	switch t.Name {
	case ConstClassID:
		want = make(map[string]int, NumPlayerClasses)
		for _, pc := range PlayerClasses() {
			want[pc.String()] = int(pc)
		}
	case ConstRace:
		want = make(map[string]int, NumRaces)
		for r := range Race(NumRaces) {
			want[r.String()] = int(r)
		}
	case ConstCategory:
		want = make(map[string]int, NumCategoryTypes)
		for ct := range CategoryType(NumCategoryTypes) {
			want[ct.String()] = int(ct)
		}
	default:
		return
	}
	for _, name := range slices.Sorted(maps.Keys(t.Ints)) {
		v := t.Ints[name]
		w, ok := want[name]
		switch {
		case !ok:
			p.addf("%s: %s is not a value of the generated enum", where, name)
		case w != v:
			p.addf("%s: %s is %d, the generated enum has %d", where, name, v, w)
		}
	}
	var missing []string
	for _, name := range slices.Sorted(maps.Keys(want)) {
		if _, ok := t.Ints[name]; !ok {
			missing = append(missing, name)
		}
	}
	if len(missing) > 0 {
		const shown = 5
		list := strings.Join(missing[:min(len(missing), shown)], ", ")
		if len(missing) > shown {
			list += ", ..."
		}
		p.addf("%s: %d values of the generated enum are missing: %s", where, len(missing), list)
	}
}

// Table returns the table with the given Lua name.
func (c *Constants) Table(name string) (*ConstantTable, bool) {
	i, ok := c.byName[name]
	if !ok {
		return nil, false
	}
	return &c.Tables[i], true
}

// Int returns an integer constant, such as Int("State", "STARTED").
func (c *Constants) Int(table, name string) (int, bool) {
	t, ok := c.Table(table)
	if !ok {
		return 0, false
	}
	v, ok := t.Ints[name]
	return v, ok
}

// String returns a string constant, such as String("QuestSound",
// "ITEMSOUND_QUEST_ACCEPT").
func (c *Constants) String(table, name string) (string, bool) {
	t, ok := c.Table(table)
	if !ok {
		return "", false
	}
	v, ok := t.Strings[name]
	return v, ok
}
